public class Main {
    public static void main(String[] args) {
        int n = 0b{nb};

        int count = 0;
        int rest = n;
        while (rest > 0) {
            count = count + (rest & 1);
            rest = rest >> 1;
        }

        System.out.println("这排格子里有几个 1：" + count);
    }
}
